glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in lowp vec4 a_color;
in mediump vec2 a_uv0;
out lowp vec4 v_color;
out mediump vec2 v_uv0;
void main () {
  v_color = a_color;
  v_uv0 = a_uv0;
  gl_Position = cc_matViewProj * vec4(a_position, 1.0);
}

glsl3.frag:
precision highp float;
uniform sampler2D texture;
uniform Blur {
  vec2 texelSize;
};
varying lowp vec4 v_color;
varying mediump vec2 v_uv0;
void main () {
  vec2 offset = texelSize * 2.0;
  vec4 color = texture2D(texture, v_uv0) * 4.0;
  color += texture2D(texture, v_uv0 + vec2(-offset.x, -offset.y));
  color += texture2D(texture, v_uv0 + vec2(0.0, -offset.y)) * 2.0;
  color += texture2D(texture, v_uv0 + vec2(offset.x, -offset.y));
  color += texture2D(texture, v_uv0 + vec2(-offset.x, 0.0)) * 2.0;
  color += texture2D(texture, v_uv0 + vec2(offset.x, 0.0)) * 2.0;
  color += texture2D(texture, v_uv0 + vec2(-offset.x, offset.y));
  color += texture2D(texture, v_uv0 + vec2(0.0, offset.y)) * 2.0;
  color += texture2D(texture, v_uv0 + vec2(offset.x, offset.y));
  gl_FragColor = color * v_color / 16.0;
}

